from pwn import remote

def query_gopher(entry):
    host = "rev.chal.csaw.io"
    port = 7070

    with remote(host, port) as conn:
        conn.send(entry.encode() + b"\r\n")
        response = conn.recvall(timeout=5)

    return response

if __name__ == "__main__":
    results = {}

    entries_to_query = ["/ibutterflies", "/caterpillar3", "/route3"]

    for entry in entries_to_query:
        results[entry] = query_gopher(entry).decode(errors="ignore")

    for entry, response in results.items():
        print(f"Query: {entry}\nResponse:\n{response}\n{'-' * 40}\n")

from pwn import *

def analyze_data_param():
    inputs = ["ibutterflies fly", "caterpillars grow"]
    key_offset = 3
    results = []

    for phrase in inputs:
        shifted_chars = "".join(chr((ord(char) - ord('a') + key_offset) % 26 + ord('a')) if char.isalpha() and char.islower() else char for char in phrase)
        results.append(shifted_chars)

    for index, result in enumerate(results):
        print(f"Original: {inputs[index]} Shifted: {result}")

if __name__ == "__main__":
    analyze_data_param()
